import{_ as t,o,c as a,a5 as r}from"./chunks/framework.DSg0KOwT.js";const u=JSON.parse('{"title":"What stays on your machine","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/what-stays-on-your-machine.md","filePath":"user-guide/what-stays-on-your-machine.md"}'),s={name:"user-guide/what-stays-on-your-machine.md"};function n(h,e,d,c,i,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="what-stays-on-your-machine" tabindex="-1">What stays on your machine <a class="header-anchor" href="#what-stays-on-your-machine" aria-label="Permalink to &quot;What stays on your machine&quot;">​</a></h1><p>The browser app parses your event log in a Web Worker on your machine. The log&#39;s contents are never sent anywhere. The app page has a Content-Security-Policy that limits the page&#39;s own requests (<code>fetch</code>, WebSocket, beacon) to the origin that served it. The policy does not cover the parse, zstd and layout workers or the docs iframe. A test does.</p><h2 id="which-modes-contact-the-network" tabindex="-1">Which modes contact the network <a class="header-anchor" href="#which-modes-contact-the-network" aria-label="Permalink to &quot;Which modes contact the network&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Network use</th></tr></thead><tbody><tr><td>Browser app, dropped or picked file</td><td>None beyond loading the app from the host that serves it.</td></tr><tr><td><strong>Try a sample run</strong></td><td>One request to the same host for the bundled sample log.</td></tr><tr><td>Docs panel</td><td>The panel is an iframe that loads pages from the same host&#39;s <code>/docs/</code>.</td></tr><tr><td>Local server (<code>sparkforensics-server</code>)</td><td>The browser talks only to the local server. When you fetch from a Spark History Server, the server makes that request, not the browser. The server listens on <code>127.0.0.1</code> only.</td></tr><tr><td>CLI and MCP tools with a log path</td><td>None.</td></tr><tr><td>CLI and MCP tools with a History Server URL</td><td>One request to that server for the event log.</td></tr></tbody></table><p>Links to other sites open only when you click them.</p><h2 id="check-it-yourself" tabindex="-1">Check it yourself <a class="header-anchor" href="#check-it-yourself" aria-label="Permalink to &quot;Check it yourself&quot;">​</a></h2><p>Open your browser&#39;s developer tools, load a log, and look at the Network tab: every request goes to the page&#39;s own origin. The policy is the <code>Content-Security-Policy</code> meta tag in the app&#39;s <code>index.html</code>. The browser test <code>e2e/no-network.test.js</code> (<code>npm run test:e2e</code>) loads the sample run and the docs panel, and fails on any request from the page, its workers or the iframe to another origin.</p><h2 id="redact-is-not-a-network-control" tabindex="-1"><code>--redact</code> is not a network control <a class="header-anchor" href="#redact-is-not-a-network-control" aria-label="Permalink to &quot;`--redact` is not a network control&quot;">​</a></h2><p><code>--redact</code> on the CLI and MCP tools pseudonymizes the application ID, application name and host names in the output, so you can share a report. It does not change which requests a mode makes.</p>',9)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
